// ========== ข้อมูลเกม ==========
  // เพลงประกอบเกม (แต่งเองไม่ติดลิขสิทธิ์)
  const MUSIC_SRC={
    title:'data:audio/mpeg;base64,',
    battle:'data:audio/mpeg;base64,',
    victory:'data:audio/mpeg;base64,',
    defeat:'data:audio/mpeg;base64,',
  };
  const _tracks={};
  let _curMusic=null, _audioReady=false;
  function _getTrack(n){
    if(!_tracks[n]){ _tracks[n]=new Audio(MUSIC_SRC[n]); _tracks[n].preload='auto'; }
    return _tracks[n];
  }
  function playMusic(n, loop){
    if(!_audioReady) { _curMusic=n; return; }
    stopMusic();
    const t=_getTrack(n);
    t.loop=!!loop; t.volume=0.5; t.currentTime=0;
    t.play().catch(()=>{});
    _curMusic=n;
  }
  function stopMusic(){
    Object.values(_tracks).forEach(t=>{t.pause();});
  }
  // Unlock audio on first user gesture, resume whatever was queued
  document.addEventListener('pointerdown', function once(){
    _audioReady=true;
    document.removeEventListener('pointerdown', once);
    if(_curMusic) playMusic(_curMusic, _curMusic==='title'||_curMusic==='battle');
  });

