// ========== โค้ดเกมหลัก ==========
const G = (() => {
  const BASE = { maxHp:1500, hp:1500, maxMp:200, mp:200, baseAtk:65, atk:65, def:10, exp:0, level:1, expToNext:100, sp:0 };

  let hero, season, eIdx, enemy, unlocked, cleared, defeated,
      resAction, busy, totalKills, startTime, inventory, itemsUsed, heroDebuffs, mpRegenTimer;

  // ตั้งค่าเริ่มต้นของเกมใหม่ทั้งหมด
  function init() {
    // ก็อปค่าเริ่มต้นมาใส่ฮีโร่ทีละตัว
    hero = {};
    for (var key in BASE) { hero[key] = BASE[key]; }
    hero.buffs = [];
    season=0; eIdx=0; enemy=null;
    unlocked=[true,false,false]; cleared=[false,false,false]; defeated=[0,0,0];
    resAction=null; busy=false; totalKills=0; startTime=Date.now();
    inventory={}; itemsUsed=0; heroDebuffs=[];
  }

  // เปลี่ยนหน้าจอ โดยซ่อนทุกหน้าแล้วโชว์เฉพาะหน้าที่ต้องการ
  function show(id) {
    document.querySelectorAll('.screen').forEach(s=>s.classList.remove('active'));
    document.getElementById(id).classList.add('active');
    // เล่นวีดีโอหน้าปกเฉพาะตอนอยู่หน้าปก
    var tv = document.getElementById('titleBgVideo');
    if(tv){ if(id==='titleScreen'){ tv.play().catch(function(){}); } else { tv.pause(); } }
    // music per screen
    if(id==='battleScreen'){ if(_curMusic!=='battle') playMusic('battle', true); }
    else if(id==='titleScreen'||id==='seasonScreen'){ if(_curMusic!=='title') playMusic('title', true); }
  }

  // ===== หน้าเลือกฤดูกาล =====
  function goTitle() { clearInterval(mpRegenTimer); saveGameData(); var v=document.getElementById('bgVideo'); if(v) v.pause(); show('titleScreen'); }
  let introPlayed = false;
  function goSeasons() {
    if(!getSession()){ renderAccountModal(); document.getElementById('registerModal').classList.add('open'); return; }
    if(!introPlayed){ introPlayed = true; playIntro(goSeasons); return; }
    clearInterval(mpRegenTimer); saveGameData(); var v=document.getElementById('bgVideo'); if(v) v.pause(); renderSeasonCards(); renderHeroStatus(); show('seasonScreen');
  }

  function renderSeasonCards() {
    const el = document.getElementById('seasonCards');
    el.innerHTML = '';
    SEASONS.forEach((s,i)=>{
      const ok=unlocked[i], done=cleared[i], count=defeated[i], total=s.enemies.length;
      const card = document.createElement('div');
      card.className = 'season-card'+(ok?'':' locked');
      if(ok) {
        card.style.borderColor = s.color+'30';
        card.style.boxShadow = `0 0 20px ${s.color}12, inset 0 1px 0 ${s.color}20`;
        card.onclick = ()=>startSeason(i);
      }
      card.innerHTML = `
        <div class="sc-band" style="background:linear-gradient(90deg,${s.color},${s.color}88);box-shadow:0 0 10px ${s.color}55"></div>
        <div class="sc-body">
          <div class="sc-head">
            <div class="sc-emoji" style="color:${s.color}">${s.emoji}</div>
            <div>
              <div class="sc-name" style="color:${ok?s.color:'#4b5a7a'}">${s.name}</div>
              <div class="sc-info">มอนสเตอร์ ${total-1} ตัว + บอส 1 ตัว</div>
            </div>
            ${!ok?'<div class="sc-lock">🔒</div>':''}
          </div>
          ${ok?`
            <div class="progress-row"><span>ความคืบหน้า</span><span style="color:${s.color}">${count}/${total}</span></div>
            <div class="bar-wrap" style="height:6px"><div class="bar-fill" style="width:${(count/total)*100}%;background:${s.color};box-shadow:0 0 8px ${s.color}80"></div></div>
            ${done?`<div class="cleared-tag" style="color:${s.color}">✅ ผ่านแล้ว!</div>`:''}
          `:''}
        </div>`;
      el.appendChild(card);
    });
  }

  function renderHeroStatus() {
    const h=hero, el=document.getElementById('heroStatusEl');
    var items = countItems();
    el.innerHTML = `
      <div style="display:flex;gap:14px;margin-bottom:10px">
        <div style="flex:1">
          <div class="bar-label"><span style="color:#6ee7b7">❤️ HP</span><span>${h.hp}/${h.maxHp}</span></div>
          <div class="bar-wrap" style="margin-top:5px"><div class="bar-fill hp-bar" style="width:${Math.max(0,h.hp/h.maxHp*100)}%"></div></div>
        </div>
        <div style="flex:1">
          <div class="bar-label"><span style="color:#93c5fd">💧 MP</span><span>${h.mp}/${h.maxMp}</span></div>
          <div class="bar-wrap" style="margin-top:5px"><div class="bar-fill mp-bar" style="width:${Math.max(0,h.mp/h.maxMp*100)}%"></div></div>
        </div>
      </div>
      <div style="display:flex;gap:8px">
        <div class="stat-box" style="flex:none;padding:5px 14px">⚔️ ${h.atk}</div>
        <div class="stat-box" style="flex:none;padding:5px 14px">🛡️ ${h.def}</div>
        <div class="stat-box" style="flex:none;padding:5px 14px">🎒 ${items} ชิ้น</div>
      </div>`;
  }

  // ===== เริ่มด่าน =====
  function startSeason(idx) {
    season = idx;
    hero.hp=hero.maxHp; hero.mp=hero.maxMp; hero.buffs=[]; heroDebuffs=[]; startTime=Date.now(); itemsUsed=0;
    if(cleared[idx]) { defeated[idx]=0; }
    eIdx=0; spawnEnemy(0); show('battleScreen'); renderBattle();
    clearInterval(mpRegenTimer); mpRegenTimer = null;
  }

  function spawnEnemy(idx) {
    const raw = SEASONS[season].enemies[idx];
    // ก็อปข้อมูลศัตรูจากตาราง แล้วเพิ่มค่าสถานะเริ่มต้น
    enemy = {};
    for (var key in raw) { enemy[key] = raw[key]; }
    enemy.maxHp = raw.hp;
    enemy.curHp = raw.hp;
    enemy.stunned = false;
    enemy.weakDef = 0;
    enemy.weakTurns = 0;
    enemy.atkBuff = 0;
    enemy.atkBuffTurns = 0;
    eIdx = idx;
  }

  // ===== วาดหน้าจอต่อสู้ =====
  function renderBattle() {
    const s=SEASONS[season], e=enemy;
    const badge = document.getElementById('bSeasonBadge');
    badge.textContent = `${s.emoji} ${s.name}`;
    badge.style.cssText = `font-size:12px;font-weight:800;padding:5px 14px;border-radius:20px;background:${s.color}18;color:${s.color};border:1px solid ${s.color}40;letter-spacing:1px`;
    document.getElementById('bProgress').textContent = `${eIdx+1} / ${s.enemies.length}`;

    // Dynamic season glow on enemy zone
    const ez = document.getElementById('enemyZone');
    const TINTS=[
      'radial-gradient(ellipse at 50% 60%, rgba(6,182,212,0.22) 0%, rgba(6,182,212,0.08) 50%, transparent 80%)',
      'radial-gradient(ellipse at 55% 55%, rgba(249,115,22,0.28) 0%, rgba(239,68,68,0.14) 50%, transparent 80%)',
      'radial-gradient(ellipse at 50% 45%, rgba(147,197,253,0.25) 0%, rgba(56,189,248,0.12) 50%, transparent 80%)'
    ];
    ez.style.setProperty('--season-tint', TINTS[s.id]||TINTS[0]);
    const BGS=[
      'url(\'data:image/jpeg;base64,\')',
      'url(\'data:image/jpeg;base64,\')',
      'url(\'data:image/jpeg;base64,\')'
    ];
    // ใส่วีดีโอพื้นหลังตามฤดู (ภาพนิ่งยังแสดงรองอยู่ข้างใต้ เผื่อวีดีโอเล่นไม่ได้)
    const vid = document.getElementById('bgVideo');
    const tintLayer = document.getElementById('seasonTintLayer');
    if(SEASON_BG_VIDS[s.id]){
      ez.style.setProperty('--season-bg', BGS[s.id]||BGS[0]);
      tintLayer.style.background = TINTS[s.id]||TINTS[0];
      if(vid.dataset.season !== String(s.id)){
        vid.src = SEASON_BG_VIDS[s.id];
        vid.dataset.season = String(s.id);
        vid.load();
      }
      vid.classList.add('active');
      vid.play().catch(()=>{});
    } else {
      ez.style.setProperty('--season-bg', BGS[s.id]||BGS[0]);
      tintLayer.style.background = '';
      vid.classList.remove('active');
      vid.pause();
    }

    // Halo color
    const halo = document.getElementById('eHalo');
    halo.style.boxShadow = `0 0 28px ${s.color}40`;
    halo.style.background = `radial-gradient(ellipse, ${s.color}30 0%, transparent 70%)`;


    document.getElementById('bossTag').innerHTML = e.isBoss?`<div class="boss-tag">⭐ BOSS ⭐</div>`:'';
    const sp = document.getElementById('eSprite');
    if (e.vidIdx !== undefined && ENEMY_VIDS[e.vidIdx]) {
      sp.innerHTML = `<video src="${ENEMY_VIDS[e.vidIdx]}" loop muted playsinline style="height:1em;width:auto;display:block;object-fit:contain;pointer-events:none;"></video>`;
      const v = sp.querySelector('video'); if(v) v.play().catch(()=>{});
    } else if (e.img) {
      sp.innerHTML = `<img src="data:image/webp;base64,${e.img}" style="height:1em;width:auto;display:block;object-fit:contain;image-rendering:auto">`;
    } else { sp.textContent = e.emoji; }
    sp.className = 'e-sprite' + (e.isBoss ? ' boss' : '');
    document.getElementById('eName').textContent = e.name;
    document.getElementById('stunIndicator').style.display='none';
    document.getElementById('weakIndicator').style.display='none';
    updateEHp(); updateHHp(); renderBuffs(); renderDebuffs(); renderSkills(true);
    const hv=document.getElementById('heroIdleVid'); if(hv) hv.play().catch(()=>{});
    document.getElementById('blog').innerHTML='';
    log(`${e.isBoss?'⭐ BOSS':'👾'} ${e.name} ปรากฏตัว!`+(e.sp?` — สกิลพิเศษ: ${e.sp.e}${e.sp.name}`:''),'s');
    busy=false;
  }

  function updateEHp() {
    const pct = Math.max(0,enemy.curHp/enemy.maxHp*100);
    document.getElementById('eHpText').textContent = `HP: ${Math.max(0,enemy.curHp)} / ${enemy.maxHp}`;
    document.getElementById('eHpBar').style.width = pct+'%';
  }

  function updateHHp() {
    const h=hero;
    document.getElementById('hHpTxt').textContent = `${Math.max(0,h.hp)}/${h.maxHp}`;
    document.getElementById('hMpTxt').textContent = `${h.mp}/${h.maxMp}`;
    document.getElementById('hHpBar').style.width = Math.max(0,h.hp/h.maxHp*100)+'%';
    document.getElementById('hMpBar').style.width = Math.max(0,h.mp/h.maxMp*100)+'%';
    document.getElementById('hAtk').textContent = h.atk;
    document.getElementById('hDef').textContent = h.def;
    const expPct = h.expToNext>0 ? Math.min(100,h.exp/h.expToNext*100) : 100;
    const lvEl=document.getElementById('heroLv'); if(lvEl) lvEl.textContent=`Lv.${h.level}`;
    const ebEl=document.getElementById('heroExpBar'); if(ebEl) ebEl.style.width=expPct+'%';
    const etEl=document.getElementById('heroExpTxt'); if(etEl) etEl.textContent=`${h.exp}/${h.expToNext}`;
    const ubtn=document.getElementById('upgradeBtn');
    if(ubtn){ ubtn.style.display=h.sp>0?'flex':'none'; const sb=document.getElementById('spBadge'); if(sb) sb.textContent=h.sp; }
  }

  const BUFF_CSS = { atkMult:'c-atk', defBonus:'c-def', dmgMult:'c-dmg', stunImmune:'c-imm' };
  const DBF_CSS  = { poison:'c-poi', burn:'c-burn', bleed:'c-bled', atk_down:'c-atk_d', def_down:'c-def_d', stun:'c-stun', mp_drain:'c-mp' };
  const DBF_LBL  = { poison:'☠️ พิษ', burn:'🔥 ไฟ', bleed:'🩸 เลือด', atk_down:'⚔️↓', def_down:'🛡️↓', stun:'💫 Stun', mp_drain:'💧↓ MP' };

  function renderBuffs() {
    var cnt = countItems();
    document.getElementById('itemCount').textContent = cnt>0?cnt:'';
    document.getElementById('itemBtnMain').disabled = busy||cnt===0;
    document.getElementById('buffRow').innerHTML = (hero.buffs||[]).map(b=>
      `<span class="chip ${BUFF_CSS[b.type]||'c-def'}">${b.emoji} ${b.label} (${b.turns})</span>`).join('');
  }

  function renderDebuffs() {
    document.getElementById('debuffRow').innerHTML = heroDebuffs.map(d=>{
      const label = DBF_LBL[d.t]||d.t;
      const val   = d.t==='atk_down'?`-${Math.round(d.v*100)}%`:d.t==='mp_drain'?`-${d.v}MP`:d.t==='def_down'?`-${d.v}DEF`:d.t==='stun'?'':'';
      const turns = d.n>0?` (${d.n}T)`:'';
      return `<span class="chip ${DBF_CSS[d.t]||'c-poi'}">${label} ${val}${turns}</span>`;
    }).join('');
  }

  function renderSkills(enable) {
    const grid = document.getElementById('skillGrid');
    grid.innerHTML='';
    SKILLS.forEach((sk,i)=>{
      const can=sk.mp<=hero.mp;
      const wrap=document.createElement('div');
      wrap.className='sk-wrap';

      const btn=document.createElement('button');
      btn.className='sk-btn';
      btn.style.setProperty('--sk-color', sk.color);
      btn.disabled=!enable||busy||!can;
      btn.innerHTML=`<span class="sk-icon">${sk.emoji}</span><span class="sk-mp${sk.mp===0?' free':''}">${sk.mp===0?'ฟรี':sk.mp+'MP'}</span>`;
      btn.onclick=()=>useSkill(i);

      const lbl=document.createElement('div');
      lbl.className='sk-lbl';
      lbl.textContent=sk.name;

      wrap.appendChild(btn);
      wrap.appendChild(lbl);
      grid.appendChild(wrap);
    });
  }

  function lockSkills()   { busy=true;  renderSkills(false); renderBuffs(); }
  function unlockSkills() { busy=false; updateHHp(); renderSkills(true); renderBuffs(); }

  // นับจำนวนไอเท็มทั้งหมดในกระเป๋า
  function countItems() {
    var total = 0;
    for (var key in inventory) {
      total = total + inventory[key];
    }
    return total;
  }

  // ===== ฟังก์ชันช่วยคำนวณบัฟ =====
  // คำนวณตัวคูณพลังโจมตีจากบัฟทั้งหมด
  function getAtkMult() {
    var result = 1;
    var buffs = hero.buffs || [];
    for (var i = 0; i < buffs.length; i++) {
      if (buffs[i].type === 'atkMult') { result = result * buffs[i].value; }
    }
    return result;
  }
  // คำนวณตัวคูณดาเมจ
  function getDmgMult() {
    var result = 1;
    var buffs = hero.buffs || [];
    for (var i = 0; i < buffs.length; i++) {
      if (buffs[i].type === 'dmgMult') { result = result * buffs[i].value; }
    }
    return result;
  }
  // รวมค่าป้องกันที่เพิ่มจากบัฟ
  function getDefBonus() {
    var total = 0;
    var buffs = hero.buffs || [];
    for (var i = 0; i < buffs.length; i++) {
      if (buffs[i].type === 'defBonus') { total = total + buffs[i].value; }
    }
    return total;
  }
  function hasStunImmune(){ return (hero.buffs||[]).some(b=>b.type==='stunImmune'); }
  // คำนวณพลังโจมตีที่ลดลงจากดีบัฟ
  function getAtkDown() {
    var result = 1;
    for (var i = 0; i < heroDebuffs.length; i++) {
      if (heroDebuffs[i].t === 'atk_down') { result = result * (1 - heroDebuffs[i].v); }
    }
    return result;
  }
  // รวมค่าป้องกันที่โดนลดจากดีบัฟ
  function getDefDown() {
    var total = 0;
    for (var i = 0; i < heroDebuffs.length; i++) {
      if (heroDebuffs[i].t === 'def_down') { total = total + heroDebuffs[i].v; }
    }
    return total;
  }
  // เช็คว่าฮีโร่โดนสตันอยู่หรือไม่
  function isHeroStunned() {
    for (var i = 0; i < heroDebuffs.length; i++) {
      if (heroDebuffs[i].t === 'stun') { return true; }
    }
    return false;
  }

  function tickBuffs() {
    // ลดอายุบัฟลง 1 เทิร์น แล้วลบอันที่หมดอายุ
    var oldBuffs = hero.buffs || [];
    var aliveBuffs = [];
    for (var i = 0; i < oldBuffs.length; i++) {
      oldBuffs[i].turns = oldBuffs[i].turns - 1;
      if (oldBuffs[i].turns > 0) { aliveBuffs.push(oldBuffs[i]); }
    }
    hero.buffs = aliveBuffs;
  }
  function tickDebuffs() {
    // ลดจำนวนเทิร์นของดีบัฟทีละอัน
    // ถ้าเพิ่งโดนเทิร์นนี้ (fresh) จะยังไม่นับ เพื่อให้ดีบัฟอยู่ถึงเทิร์นหน้า
    var newList = [];
    for (var i = 0; i < heroDebuffs.length; i++) {
      var d = heroDebuffs[i];
      if (d.fresh) {
        d.fresh = false;   // เอาป้าย fresh ออก แต่ยังไม่ลดเทิร์น
      } else if (d.n > 0) {
        d.n = d.n - 1;     // ลดเทิร์นลง 1
      }
      if (d.n > 0) {       // เก็บเฉพาะดีบัฟที่ยังไม่หมดเวลา
        newList.push(d);
      }
    }
    heroDebuffs = newList;
    renderDebuffs();
  }
  function applyDoT() {
    // รวมดาเมจจากพิษ ไฟ และเลือดไหล
    var dot = 0;
    for (var i = 0; i < heroDebuffs.length; i++) {
      var t = heroDebuffs[i].t;
      if (t === 'poison' || t === 'burn' || t === 'bleed') {
        dot = dot + heroDebuffs[i].v;
      }
    }
    if(dot>0){ hero.hp=Math.max(0,hero.hp-dot); log(`☠️ สถานะเสีย → HP -${dot}`,'d'); updateHHp(); }
    return hero.hp>0;
  }
  function addDebuff(db) {
    if(db.t==='stun' && hasStunImmune()){ log('🛡️ วัคซีนกัน Stun!','h'); return; }
    if(db.t==='mp_drain'){ hero.mp=Math.max(0,hero.mp-db.v); log(`🌑 ดูดพลัง → MP -${db.v}`,'d'); updateHHp(); return; }
    // ถ้ามีดีบัฟชนิดเดียวกันอยู่แล้ว ให้ต่ออายุแทนการซ้อน
    var ex = null;
    for (var i = 0; i < heroDebuffs.length; i++) {
      if (heroDebuffs[i].t === db.t) { ex = heroDebuffs[i]; break; }
    }
    if(ex){ ex.n=Math.max(ex.n,db.n); ex.v=Math.max(ex.v,db.v); ex.fresh=true; }
    else {
      // สร้างดีบัฟใหม่ใส่ในลิสต์
      var newDebuff = {};
      for (var k in db) { newDebuff[k] = db[k]; }
      newDebuff.fresh = true;
      heroDebuffs.push(newDebuff);
    }
    renderDebuffs();
  }

  function updateWeakIndicator() {
    const el=document.getElementById('weakIndicator');
    if(enemy.weakTurns>0){ el.style.display='block'; el.textContent=`🎯 จุดอ่อน -${enemy.weakDef}DEF (${enemy.weakTurns}T)`; }
    else el.style.display='none';
  }

  // ===== ระบบต่อสู้ =====
  // ตอนผู้เล่นกดใช้สกิล
  function useSkill(i) {
    if(busy) return;
    const sk=SKILLS[i], h=hero, e=enemy;
    if(sk.mp>h.mp){ log('💧 MP ไม่พอ!','s'); return; }
    lockSkills();
    if(!applyDoT()){ setTimeout(onHeroDead,750); return; }
    if(isHeroStunned()){
      heroDebuffs=heroDebuffs.filter(d=>d.t!=='stun');
      log('💫 คุณถูก Stun! ข้ามเทิร์น','d');
      renderDebuffs(); h.mp=Math.min(h.maxMp,h.mp+10);
      setTimeout(enemyTurn,800); return;
    }
    h.mp -= sk.mp;
    if(sk.type==='scan'){
      const fact=DISEASE_FACTS[e.name]||'ไม่พบข้อมูลโรคนี้';
      document.getElementById('factTitle').textContent=`🔬 ${e.name}`;
      document.getElementById('factBody').textContent=fact;
      document.getElementById('factModal').classList.add('open');
      log(`🔬 เซลล์ตรวจจับ → อ่านเกร็ดความรู้ ${e.emoji} ${e.name}`,'p');
      return;
    }
    if(sk.type==='cleanse'){
      const count=heroDebuffs.length;
      heroDebuffs=[];
      renderDebuffs();
      floatDmg('✨ล้างสถานะ!','#c4b5fd');
      log(`🌀 ผ้าคลุมเม็ดเลือด → ล้างดีบัฟ ${count} สถานะ`,'h');
      updateHHp(); setTimeout(enemyTurn,850); return;
    }
    if(sk.type==='barrier'){
      hero.buffs.push({type:'defBonus',value:60,turns:4,label:'DEF+60',emoji:'🛡️'});
      log(`🛡️ บาเรียภูมิคุ้มกัน → DEF+60 (4T)`,'h');
      floatDmg('🛡️DEF+60','#93c5fd'); renderBuffs();
      setTimeout(enemyTurn,850); return;
    }
    const weak=e.weakDef||0;
    const atkVal=Math.floor(h.atk*getAtkMult()*getAtkDown()*sk.mult*getDmgMult());
    const vari=Math.floor(atkVal*0.15);
    const effDef=sk.type==='pierce'?Math.max(0,Math.floor(e.def*0.4)-weak):Math.max(0,e.def-weak);
    let dmg=Math.max(5,atkVal+rng(-vari,vari)-effDef);
    const crit=Math.random()<0.15; if(crit) dmg=Math.floor(dmg*1.5);
    e.curHp-=dmg;
    if(sk.type==='pierce'){
      log(`⚔️ ดาบแอนติบอดี → ${dmg}${crit?' 💥CRIT!':''} ┊ ทะลุเกราะ 60%`,'p');
    }
    heroAttackAnim(); shakeEnemy(); floatDmg(dmg+(crit?'!!':''),crit?'#fbbf24':'#fca5a5');
    updateEHp(); updateHHp();
    if(e.curHp<=0){ setTimeout(onEnemyDead,800); return; }
    setTimeout(enemyTurn,950);
  }

  // เทิร์นของศัตรู (โจมตีกลับหรือใช้สกิลพิเศษ)
  function enemyTurn() {
    const h=hero, e=enemy;
    if(e.stunned){
      e.stunned=false; document.getElementById('stunIndicator').style.display='none';
      log(`⭐ ${e.name} ถูก Stun! ข้ามเทิร์น`,'s');
      tickEnemyWeak(); tickBuffs(); tickDebuffs();
      h.mp=Math.min(h.maxMp,h.mp+10);
      setTimeout(unlockSkills,400); return;
    }
    const sp=e.sp, useSpecial=sp&&Math.random()<sp.ch;
    enemyAttackAnim();
    if(useSpecial){ setTimeout(shakeHero,250); doEnemySpecial(sp); }
    else {
      const atkTotal=e.atk+(e.atkBuff||0), vari=Math.floor(atkTotal*0.2);
      const defTot=Math.max(0,h.def+getDefBonus()-getDefDown());
      const dmg=Math.max(5,atkTotal+rng(-vari,vari)-defTot);
      h.hp=Math.max(0,h.hp-dmg);
      log(`${e.emoji} ${e.name} โจมตี → ${dmg}${getDefBonus()>0?' 🛡️':''}`, 'e');
      floatDmg('-'+dmg,'#fca5a5','hero');
      setTimeout(shakeHero,250); updateHHp();
    }
    if(e.atkBuffTurns>0){ e.atkBuffTurns--; if(e.atkBuffTurns<=0) e.atkBuff=0; }
    tickEnemyWeak(); tickBuffs(); tickDebuffs();
    h.mp=Math.min(h.maxMp,h.mp+10); renderBuffs();
    if(h.hp<=0){ setTimeout(onHeroDead,750); return; }
    setTimeout(unlockSkills,550);
  }

  function doEnemySpecial(sp) {
    const h=hero, e=enemy;
    const atkTotal=e.atk+(e.atkBuff||0), defTot=Math.max(0,h.def+getDefBonus()-getDefDown());
    switch(sp.type){
      case 'debuff':{ const d=Math.max(3,Math.floor(atkTotal*sp.pm+rng(-10,10))-defTot); h.hp=Math.max(0,h.hp-d); addDebuff(sp.db); log(`${sp.e} ${e.name} [${sp.name}] → ${d} + ${DBF_LBL[sp.db.t]||sp.db.t}!`,'d'); floatDmg('-'+d,'#f87171','hero'); updateHHp(); break; }
      case 'power':{ const d=Math.max(5,Math.floor(atkTotal*sp.pm+rng(-15,15))-defTot); h.hp=Math.max(0,h.hp-d); log(`${sp.e} ${e.name} [${sp.name}] → ${d}! 💥`,'d'); floatDmg('-'+d+'💥','#fb923c','hero'); updateHHp(); break; }
      case 'double':{ let t=0; for(let j=0;j<2;j++){ const d=Math.max(3,Math.floor(atkTotal*sp.pm+rng(-8,8))-defTot); t+=d; h.hp=Math.max(0,h.hp-d); } log(`${sp.e} ${e.name} [${sp.name}] → 2 ครั้ง รวม ${t}!`,'d'); floatDmg('-'+t,'#f87171','hero'); updateHHp(); break; }
      case 'triple':{ let t=0; for(let j=0;j<3;j++){ const d=Math.max(3,Math.floor(atkTotal*sp.pm+rng(-8,8))-defTot); t+=d; h.hp=Math.max(0,h.hp-d); } log(`${sp.e} ${e.name} [${sp.name}] → 3 ครั้ง รวม ${t}!`,'d'); floatDmg('-'+t,'#f87171','hero'); updateHHp(); break; }
      case 'selfheal':{ const ha=Math.floor(e.maxHp*sp.hp); e.curHp=Math.min(e.maxHp,e.curHp+ha); log(`${sp.e} ${e.name} [${sp.name}] → ฟื้น +${ha}!`,'d'); updateEHp(); floatDmg('+'+ha,'#6ee7b7','enemy'); const d=Math.max(3,Math.floor(atkTotal*0.5+rng(-5,5))-defTot); h.hp=Math.max(0,h.hp-d); floatDmg('-'+d,'#f87171','hero'); updateHHp(); break; }
      case 'selfbuff':{ e.atkBuff=(sp.ab||0); e.atkBuffTurns=(sp.bt||2); log(`${sp.e} ${e.name} [${sp.name}] → ATK+${sp.ab} (${sp.bt}T)!`,'d'); const d=Math.max(3,Math.floor(atkTotal*sp.pm+rng(-5,5))-defTot); h.hp=Math.max(0,h.hp-d); floatDmg('-'+d,'#f87171','hero'); updateHHp(); break; }
    }
  }

  function tickEnemyWeak() {
    if(enemy.weakTurns>0){ enemy.weakTurns--; if(enemy.weakTurns<=0) enemy.weakDef=0; updateWeakIndicator(); }
  }

  // ===== ตอนตาย =====
  let pendingLoot=null;
  function onEnemyDead() {
    const s=SEASONS[season], isLast=eIdx>=s.enemies.length-1;
    totalKills++; defeated[season]++;
    hero.mp=Math.min(hero.maxMp,hero.mp+35);
    const drops=calcDrops(enemy);
    const expGain=enemy.isBoss?120:40;
    const snap={name:enemy.name, isLast, s};
    pendingLoot={drops, expGain, snap};
    setTimeout(()=>{ document.getElementById('lootBox').style.display='flex'; },600);
  }
  function onHeroDead() {
    playMusic('defeat', false);
    showResult('💀','คุณพ่ายแพ้...',`${enemy.name} เอาชนะคุณได้\nลองใหม่ตั้งแต่ต้นฤดูกาลนี้`,'🔄 ลองใหม่','retry');
  }

  function calcDrops(e) {
    const sid=season, drops=[];
    ITEMS.forEach(item=>{
      if(item.bossOnly&&!e.isBoss) return;
      if(item.id==='healPotion'&&sid!==0) return;
      if(item.id==='ironShield'&&sid!==2) return;
      if(Math.random()<item.dropRate) drops.push(item);
    });
    return drops;
  }

  // เปิดกล่องสมบัติหลังชนะ
  function openChest() {
    if(!pendingLoot) return;
    document.getElementById('lootBox').style.display='none';
    const {drops, expGain} = pendingLoot;
    let html=`<div class="loot-row"><div class="lr-emoji">✨</div><div class="lr-name">ประสบการณ์</div><div class="lr-val">+${expGain} EXP</div></div>`;
    drops.forEach(item=>{ html+=`<div class="loot-row"><div class="lr-emoji">${item.emoji}</div><div class="lr-name">${item.name}</div><div class="lr-val">${item.desc}</div></div>`; });
    document.getElementById('lootRows').innerHTML=html;
    document.getElementById('lootModal').classList.add('open');
  }

  // เก็บของรางวัล + ได้ EXP
  function collectLoot() {
    document.getElementById('lootModal').classList.remove('open');
    if(!pendingLoot) return;
    const {drops, expGain, snap} = pendingLoot;
    pendingLoot=null;

    drops.forEach(item=>{
      if(item.type==='equip'){ hero.atk+=15; hero.baseAtk+=15; floatDmg('⚔️ATK+15','#fde68a'); }
      else { inventory[item.id]=(inventory[item.id]||0)+1; }
    });

    hero.exp+=expGain;
    let leveled=false;
    while(hero.exp>=hero.expToNext){
      hero.exp-=hero.expToNext; hero.level++; hero.expToNext=hero.level*100; hero.sp++; leveled=true;
    }
    if(leveled){ floatDmg(`⬆️ Lv.${hero.level}!`,'#fde68a'); log(`🌟 LEVEL UP! Lv.${hero.level} — ได้ 1 Stat Point`,'h'); }
    updateHHp();

    if(snap.isLast){
      cleared[season]=true; if(season<2) unlocked[season+1]=true;
      const s=snap.s, cur=season;
      setTimeout(()=>{
        if(cur===2) startQuiz(cur, ()=>setTimeout(showClear,400));
        else { const ns=SEASONS[cur+1]; playMusic('victory', false); startQuiz(cur, ()=>setTimeout(()=>showResult('🎉',`${s.emoji} ${s.name} ผ่านแล้ว!`,`ปราบ ${s.name}สำเร็จ!\n${ns.emoji} ${ns.name} ถูกปลดล็อคแล้ว`,'➡️ ฤดูถัดไป','nextSeason'),400)); }
      }, 500);
    } else {
      const heal=Math.floor(hero.maxHp*0.08);
      hero.hp=Math.min(hero.maxHp,hero.hp+heal);
      log(`✅ ${snap.name} พ่ายแพ้! ฟื้น HP+${heal}`,'h'); updateHHp();
      setTimeout(()=>{ spawnEnemy(eIdx+1); renderBattle(); unlockSkills(); },800);
    }
    saveGameData(); // persist EXP/level-ups/items/unlocks right after each kill
  }

  // ===== อัพเกรดตัวละคร =====
  function showUpgradeModal() { document.getElementById('upgradeSP').textContent=`SP คงเหลือ: ${hero.sp}`; document.getElementById('upgradeModal').classList.add('open'); }
  function hideUpgradeModal() { document.getElementById('upgradeModal').classList.remove('open'); }
  function spendSP(stat) {
    if(!hero.sp) return;
    hero.sp--;
    switch(stat){
      case 'hp': hero.maxHp+=100; hero.hp=Math.min(hero.maxHp,hero.hp+50); floatDmg('❤️ HP+100','#4ade80'); break;
      case 'atk': hero.atk+=8; hero.baseAtk+=8; floatDmg('⚔️ ATK+8','#fde68a'); break;
      case 'def': hero.def+=5; floatDmg('🛡️ DEF+5','#93c5fd'); break;
      case 'mp': hero.maxMp+=30; hero.mp=Math.min(hero.maxMp,hero.mp+15); floatDmg('💧 MP+30','#67e8f9'); break;
    }
    log(`⬆️ อัพ ${stat.toUpperCase()}!`,'h'); updateHHp(); saveGameData();
    if(!hero.sp) hideUpgradeModal();
    else document.getElementById('upgradeSP').textContent=`SP คงเหลือ: ${hero.sp}`;
  }

  // ===== กล่องเกร็ดความรู้ =====
  function closeFact() {
    document.getElementById('factModal').classList.remove('open');
    setTimeout(enemyTurn, 600);
  }

  // ===== แบบทดสอบท้ายด่าน =====
  let quizState=null;
  // เริ่มแบบทดสอบความรู้ท้ายฤดู
  function startQuiz(seasonIdx, afterFn) {
    quizState={ seasonIdx, qIdx:0, score:0, expBonus:0, afterFn };
    renderQuizQ();
    show('quizScreen');
  }
  function renderQuizQ() {
    const qs=QUIZZES[quizState.seasonIdx];
    const q=qs[quizState.qIdx];
    const s=SEASONS[quizState.seasonIdx];
    document.getElementById('quizBadge').textContent=`${s.emoji} ${s.name}`;
    document.getElementById('quizProg').textContent=`คำถาม ${quizState.qIdx+1}/${qs.length}`;
    document.getElementById('quizQ').textContent=q.q;
    document.getElementById('quizFeedback').style.display='none';
    document.getElementById('quizNextBtn').style.display='none';
    document.getElementById('quizChoices').innerHTML=q.a.map((a,i)=>
      `<button class="quiz-choice" onclick="G.answerQuiz(${i})">${a}</button>`).join('');
  }
  function answerQuiz(idx) {
    const qs=QUIZZES[quizState.seasonIdx];
    const q=qs[quizState.qIdx];
    const correct=idx===q.c;
    document.querySelectorAll('.quiz-choice').forEach((btn,i)=>{
      btn.disabled=true;
      if(i===q.c) btn.classList.add('correct');
      else if(i===idx&&!correct) btn.classList.add('wrong');
    });
    if(correct){ quizState.score++; quizState.expBonus+=30; }
    const fb=document.getElementById('quizFeedback');
    fb.className='quiz-feedback '+(correct?'ok':'err');
    fb.style.display='block';
    fb.textContent=correct?`✅ ถูกต้อง! +30 EXP`:`❌ ไม่ถูก — คำตอบที่ถูก: ${q.a[q.c]}`;
    const nb=document.getElementById('quizNextBtn');
    nb.style.display='block';
    nb.textContent=quizState.qIdx+1>=qs.length?'🏁 ดูผลลัพธ์':'ถัดไป ➡️';
  }
  function nextQuizQ() {
    quizState.qIdx++;
    const qs=QUIZZES[quizState.seasonIdx];
    if(quizState.qIdx>=qs.length){
      if(quizState.expBonus>0){
        hero.exp+=quizState.expBonus;
        while(hero.exp>=hero.expToNext){ hero.exp-=hero.expToNext; hero.level++; hero.expToNext=hero.level*100; hero.sp++; }
        updateHHp();
      }
      saveGameData();
      quizState.afterFn();
    } else { renderQuizQ(); }
  }

  // ===== ไอเท็ม =====
  function showItems() { if(busy)return; renderItemList(); document.getElementById('itemModal').classList.add('open'); }
  function hideItems() { document.getElementById('itemModal').classList.remove('open'); }
  function renderItemList() {
    const list=document.getElementById('itemList');
    const keys=Object.keys(inventory).filter(k=>inventory[k]>0);
    if(!keys.length){ list.innerHTML='<div class="empty-bag">🎒 กระเป๋าว่างเปล่า<br><span style="font-size:12px">กำจัดศัตรูเพื่อเก็บไอเทม</span></div>'; return; }
    list.innerHTML=keys.map(id=>{
      const it=ITEMS.find(x=>x.id===id); if(!it)return'';
      return `<div class="item-row"><div class="item-emoji">${it.emoji}</div>
        <div class="item-info"><div class="item-name">${it.name}</div><div class="item-desc">${it.desc}</div><div class="item-cnt">มีอยู่: ${inventory[id]} ชิ้น</div></div>
        <button class="use-btn" onclick="G.useItem('${id}')">ใช้</button></div>`;
    }).join('');
  }
  function useItem(itemId) {
    const item=ITEMS.find(x=>x.id===itemId);
    if(!item||!inventory[itemId]||inventory[itemId]<=0)return;
    hideItems(); lockSkills();
    inventory[itemId]--; if(inventory[itemId]<=0) delete inventory[itemId];
    itemsUsed++;
    switch(item.type){
      case 'heal':{ const amt=Math.floor(hero.maxHp*0.5); hero.hp=Math.min(hero.maxHp,hero.hp+amt); heroDebuffs=heroDebuffs.filter(d=>!['poison','burn','bleed'].includes(d.t)); log(`${item.emoji} ${item.name} → HP+${amt} + ล้างสถานะ`,'i'); updateHHp(); floatDmg('+'+amt,'#6ee7b7'); renderDebuffs(); setTimeout(enemyTurn,850); break; }
      case 'buff':{ if(itemId==='warVaccine'){ hero.buffs.push({type:'dmgMult',value:1.5,turns:4,label:'DMG×1.5',emoji:'☠️'}); hero.buffs.push({type:'stunImmune',value:1,turns:4,label:'กัน Stun',emoji:'🛡️'}); } else if(itemId==='powerSerum'){ hero.buffs.push({type:'atkMult',value:1.2,turns:3,label:'ATK×1.2',emoji:'💉'}); } else if(itemId==='ironShield'){ hero.buffs.push({type:'defBonus',value:30,turns:5,label:'DEF+30',emoji:'🛡️'}); } log(`${item.emoji} ${item.name} → ${item.desc}`,'i'); renderBuffs(); setTimeout(enemyTurn,850); break; }
      case 'stun':{ enemy.stunned=true; document.getElementById('stunIndicator').style.display='block'; log(`${item.emoji} ดาวมึนงง → ศัตรูถูก Stun!`,'i'); setTimeout(enemyTurn,850); break; }
      case 'damage':{ const dmg=300; enemy.curHp-=dmg; log(`${item.emoji} ระเบิด → ${dmg}!`,'i'); heroAttackAnim(); shakeEnemy(); floatDmg(dmg+'','#fbbf24'); updateEHp(); if(enemy.curHp<=0){setTimeout(onEnemyDead,800);return;} setTimeout(enemyTurn,950); break; }
    }
  }

  // ===== หน้าสรุปผล =====
  function showResult(icon,title,sub,btnTxt,action){
    document.getElementById('resIcon').textContent=icon;
    document.getElementById('resTitle').textContent=title;
    document.getElementById('resSub').innerHTML=sub.replace('\n','<br>');
    document.getElementById('resBtn').textContent=btnTxt;
    resAction=action; clearInterval(mpRegenTimer); saveGameData(); show('resultScreen');
  }
  function doResult(){
    if(resAction==='retry'){ startSeason(season); }
    else if(resAction==='nextSeason'){ hero.hp=hero.maxHp; hero.mp=hero.maxMp; hero.buffs=[]; heroDebuffs=[]; goSeasons(); }
  }
  function showClear(){
    playMusic('victory', false);
    clearInterval(mpRegenTimer); saveGameData();
    const secs=Math.floor((Date.now()-startTime)/1000);
    const mm=String(Math.floor(secs/60)).padStart(2,'0'), ss=String(secs%60).padStart(2,'0');
    document.getElementById('clearStats').innerHTML=`
      <div>⚔️ ศัตรูกำจัด: <strong style="color:var(--gold)">${totalKills} / 15</strong></div>
      <div>🕐 เวลา: <strong style="color:var(--gold)">${mm}:${ss}</strong></div>
      <div>❤️ HP เหลือ: <strong style="color:#4ade80">${Math.max(0,hero.hp)} / ${hero.maxHp}</strong></div>
      <div>⭐ ระดับ: <strong style="color:#fde68a">Lv.${hero.level}</strong></div>
      <div>🎒 ไอเทมใช้ไป: <strong style="color:var(--gold)">${itemsUsed} ชิ้น</strong></div>`;
    show('clearScreen');
  }

  // ===== ฟังก์ชันช่วยทั่วไป =====
  // เพิ่มข้อความลงในกล่อง log การต่อสู้
  function log(txt,cls){ const el=document.getElementById('blog'); const d=document.createElement('div'); d.className='log-'+cls; d.textContent=txt; el.appendChild(d); el.scrollTop=el.scrollHeight; }
  function floatDmg(txt,color,side){
    const zone=document.getElementById('enemyZone');
    const d=document.createElement('div'); d.className='dmg-float'; d.textContent=txt;
    d.style.color=color; d.style.textShadow=`0 0 16px ${color},0 2px 4px rgba(0,0,0,0.8)`;
    if(side==='hero'){
      const sp=document.getElementById('ahSprite');
      if(sp){
        const zr=zone.getBoundingClientRect(), sr=sp.getBoundingClientRect();
        d.style.left=((sr.left+sr.right)/2-zr.left)/zr.width*100+'%';
        d.style.top=((sr.top+sr.bottom)/2-zr.top)/zr.height*100+'%';
      } else { d.style.left='13%'; d.style.top='50%'; }
    } else if(txt.startsWith('+') && side!=='enemy'){
      d.style.left='25%'; d.style.top='50%';
    } else {
      const sp=document.getElementById('eSprite');
      if(sp){
        const zr=zone.getBoundingClientRect(), sr=sp.getBoundingClientRect();
        d.style.left=((sr.left+sr.right)/2-zr.left)/zr.width*100+'%';
        d.style.top=((sr.top+sr.bottom)/2-zr.top)/zr.height*100+'%';
      } else { d.style.left='68%'; d.style.top='50%'; }
    }
    zone.appendChild(d); setTimeout(()=>d.remove(),1300);
  }
  function shakeEnemy(){ const sp=document.getElementById('eSprite'); sp.style.animation='none'; void sp.offsetWidth; sp.style.animation='shake 0.4s ease'; setTimeout(()=>sp.style.animation='floatAnim 2.5s ease-in-out infinite',500); }
  function shakeHero(){ const sp=document.getElementById('ahSprite'); if(!sp) return; sp.style.animation='none'; void sp.offsetWidth; sp.style.animation='heroHurt 0.4s ease'; setTimeout(()=>sp.style.animation='floatAnim 3s ease-in-out infinite',500); }
  function heroAttackAnim(){
    const sp=document.getElementById('ahSprite'); if(!sp) return;
    sp.style.animation='none'; void sp.offsetWidth;
    sp.style.animation='heroAttack 0.48s ease-out';
    setTimeout(()=>sp.style.animation='floatAnim 3s ease-in-out infinite',580);
    // swap idle → attack clip for a moment
    const iv=document.getElementById('heroIdleVid'), av=document.getElementById('heroAtkVid');
    if(iv&&av){
      iv.style.display='none'; av.style.display='block';
      av.currentTime=0; av.play().catch(()=>{});
      setTimeout(()=>{ av.pause(); av.style.display='none'; iv.style.display='block'; iv.play().catch(()=>{}); },1200);
    }
  }
  function enemyAttackAnim(){ const sp=document.getElementById('eSprite'); if(!sp) return; sp.style.animation='none'; void sp.offsetWidth; sp.style.animation='enemyAttack 0.48s ease-out'; setTimeout(()=>sp.style.animation='floatAnim 2.5s ease-in-out infinite',580); }
  function rng(min,max){ return Math.floor(Math.random()*(max-min+1))+min; }
  function restart(){ init(); if(getSession()) loadGameData(); updateAccountDisplay(); show('titleScreen'); }

  function showHeroLab() {
    var h = hero;
    var items = countItems();
    const stat=(emoji,lbl,val,max,col)=>`<div style="flex:1;min-width:90px;background:rgba(255,255,255,0.05);border-radius:12px;padding:12px 8px;text-align:center"><div style="font-size:10px;color:#64748b;margin-bottom:4px">${emoji} ${lbl}</div><div style="font-size:17px;font-weight:800;color:${col}">${val}${max!=null?`<span style='font-size:11px;color:#475569'>/${max}</span>`:''}</div></div>`;
    document.getElementById('heroModalContent').innerHTML=`
      <div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:16px">
        ${stat('❤️','HP',h.hp,h.maxHp,'#f87171')}
        ${stat('💧','MP',h.mp,h.maxMp,'#60a5fa')}
        ${stat('⚔️','ATK',h.atk,null,'#fb923c')}
        ${stat('🛡','DEF',h.def,null,'#34d399')}
      </div>
      <div style="font-size:11px;color:#475569;font-weight:700;letter-spacing:1px;margin-bottom:8px">สกิล</div>
      ${SKILLS.map(sk=>`<div style="display:flex;align-items:center;gap:12px;background:rgba(255,255,255,0.04);border:1px solid rgba(255,255,255,0.08);border-radius:12px;padding:11px 14px;margin-bottom:7px"><span style="font-size:26px;line-height:1">${sk.emoji}</span><div><div style="font-weight:700;color:#e2e8f0;font-size:13px">${sk.name}</div><div style="font-size:11px;color:#94a3b8;margin-top:2px">${sk.desc}</div></div></div>`).join('')}
      <div style="font-size:11px;color:#475569;font-weight:700;letter-spacing:1px;margin:12px 0 6px">ไอเทมในกระเป๋า: ${items} ชิ้น</div>
    `;
    document.getElementById('heroModal').classList.add('open');
  }
  function hideHeroLab(){ document.getElementById('heroModal').classList.remove('open'); }

  function showEncyclopedia() {
    document.getElementById('encyclopediaContent').innerHTML=SEASONS.map(s=>`
      <div style="margin-bottom:20px">
        <div style="display:flex;align-items:center;gap:8px;font-size:14px;font-weight:800;color:${s.color};margin-bottom:10px;padding-bottom:6px;border-bottom:1px solid ${s.color}30">${s.emoji} ${s.name}</div>
        ${s.enemies.map(e=>`<div style="display:flex;align-items:center;gap:10px;padding:8px 10px;margin-bottom:4px;background:rgba(255,255,255,0.03);border-radius:10px;border:1px solid rgba(255,255,255,0.06)"><span style="font-size:22px">${e.emoji}</span><div style="flex:1"><div style="font-size:13px;font-weight:700;color:#e2e8f0">${e.name}${e.isBoss?' ⭐':''}</div><div style="font-size:11px;color:#64748b;margin-top:2px">HP ${e.maxHp||e.hp} · ATK ${e.atk} · DEF ${e.def}</div></div>${e.isBoss?`<div style="font-size:10px;font-weight:700;color:#fbbf24;background:rgba(251,191,36,0.1);border:1px solid rgba(251,191,36,0.2);border-radius:6px;padding:2px 6px">BOSS</div>`:''}</div>`).join('')}
      </div>
    `).join('');
    document.getElementById('encyclopediaModal').classList.add('open');
  }
  function hideEncyclopedia(){ document.getElementById('encyclopediaModal').classList.remove('open'); }

  // ===== ตั้งค่า =====
  const SETTINGS_KEY='imm_settings';
  function loadSettings(){
    try{ return JSON.parse(localStorage.getItem(SETTINGS_KEY))||{}; }catch(e){ return {}; }
  }
  function saveSettingsData(s){ localStorage.setItem(SETTINGS_KEY,JSON.stringify(s)); }
  function showSettings(){
    const s=loadSettings();
    ['sfx','bgm','vib'].forEach(k=>{
      const btn=document.getElementById(k+'Toggle');
      if(btn){ const on=s[k]!==false; btn.className='toggle-btn '+(on?'on':'off'); }
    });
    document.getElementById('settingsModal').classList.add('open');
  }
  function hideSettings(){ document.getElementById('settingsModal').classList.remove('open'); }
  function toggleSetting(key,btn){
    const s=loadSettings(); s[key]=!( s[key]!==false );
    saveSettingsData(s); btn.className='toggle-btn '+(s[key]?'on':'off');
  }
  function resetProgress(){
    if(!confirm('รีเซตความคืบหน้าทั้งหมด?\nระดับ ไอเทม และ เส้นทางจะหายหมด')) return;
    localStorage.removeItem(SETTINGS_KEY);
    const u=getSession();
    if(u){ const db=getUsers(); if(db[u]) { db[u].save=null; saveUsersDB(db); } }
    hideSettings(); init(); updateAccountDisplay(); show('titleScreen');
  }

  // ===== ระบบสมาชิก =====
  const USERS_KEY='imm_users', SESSION_KEY='imm_session';
  function getUsers(){ try{ return JSON.parse(localStorage.getItem(USERS_KEY)||'{}'); }catch(e){ return {}; } }
  function saveUsersDB(db){ localStorage.setItem(USERS_KEY,JSON.stringify(db)); }
  function getSession(){ return localStorage.getItem(SESSION_KEY)||''; }
  function setSession(u){ if(u) localStorage.setItem(SESSION_KEY,u); else localStorage.removeItem(SESSION_KEY); }

  function saveGameData(){
    const u=getSession(); if(!u) return;
    const db=getUsers();
    if(!db[u]) return;
    // เก็บข้อมูลเกมของผู้เล่นคนนี้ลง localStorage
    var saveData = {};
    saveData.unlocked = unlocked.slice();   // slice() = ก็อปอาเรย์
    saveData.cleared = cleared.slice();
    saveData.defeated = defeated.slice();
    saveData.totalKills = totalKills;
    saveData.itemsUsed = itemsUsed;
    saveData.inventory = {};
    for (var k in inventory) { saveData.inventory[k] = inventory[k]; }
    if (hero) {
      saveData.heroStats = {
        atk: hero.atk, baseAtk: hero.baseAtk, def: hero.def,
        maxHp: hero.maxHp, maxMp: hero.maxMp, level: hero.level,
        exp: hero.exp, expToNext: hero.expToNext, sp: hero.sp
      };
    } else {
      saveData.heroStats = null;
    }
    db[u].save = saveData;
    saveUsersDB(db);
  }

  function loadGameData(){
    const u=getSession(); if(!u) return;
    const db=getUsers(); if(!db[u]||!db[u].save) return;
    const sv=db[u].save;
    if(sv.unlocked) unlocked=sv.unlocked;
    if(sv.cleared) cleared=sv.cleared;
    if(sv.defeated) defeated=sv.defeated;
    if(sv.totalKills!=null) totalKills=sv.totalKills;
    if(sv.inventory) inventory=sv.inventory;
    if(sv.itemsUsed!=null) itemsUsed=sv.itemsUsed;
    if(sv.heroStats && hero) Object.assign(hero, sv.heroStats);
  }

  function updateAccountDisplay(){
    const u=getSession();
    const el=document.getElementById('accountDisplay');
    if(el){
      if(u){ el.style.display='flex'; document.getElementById('acctName').textContent='👤 '+u; }
      else { el.style.display='none'; }
    }
  }

  let _acctTab='login';
  function renderAccountModal(tab){
    _acctTab=tab||_acctTab;
    const u=getSession();
    const body=document.getElementById('acctModalBody');
    // ดึงชื่อผู้ใช้ที่จำไว้ล่าสุดมาเติมในช่องให้อัตโนมัติ
    var rememberedUser = localStorage.getItem('imm_remember') || '';
    var rememberedPass = '';
    var userDB = getUsers();
    if (rememberedUser && userDB[rememberedUser]) {
      rememberedPass = userDB[rememberedUser].password;
    }
    if(u){
      body.innerHTML=`
        <div style="text-align:center;padding:16px 0 8px">
          <div style="font-size:28px;margin-bottom:6px">👤</div>
          <div style="font-size:15px;font-weight:700;color:#e2e8f0">${u}</div>
          <div style="font-size:12px;color:#64748b;margin-top:4px">กำลังเล่นอยู่</div>
        </div>
        <div style="padding:0 0 12px">
          <button class="btn btn-gray" style="width:100%;margin-top:8px" onclick="G.doLogout()">🚪 ออกจากระบบ</button>
        </div>`;
      return;
    }
    body.innerHTML=`
      <div class="acct-tabs">
        <button class="acct-tab${_acctTab==='login'?' active':''}" onclick="G.switchAccountTab('login')">เข้าสู่ระบบ</button>
        <button class="acct-tab${_acctTab==='register'?' active':''}" onclick="G.switchAccountTab('register')">สมัครสมาชิก</button>
      </div>
      ${_acctTab==='login'?`
        <div style="padding:0 4px 12px">
          <div style="font-size:12px;color:#94a3b8;margin-bottom:4px">ชื่อผู้ใช้</div>
          <input id="acctUser" class="setting-input" type="text" maxlength="20" placeholder="username..." autocomplete="username" value="${rememberedUser}"/>
          <div style="font-size:12px;color:#94a3b8;margin:10px 0 4px">รหัสผ่าน</div>
          <div class="pass-wrap"><input id="acctPass" class="setting-input" type="password" maxlength="40" placeholder="password..." autocomplete="current-password" value="${rememberedPass}"/><button type="button" class="pass-eye" onclick="G.togglePassEye('acctPass',this)" tabindex="-1" aria-label="แสดง/ซ่อนรหัสผ่าน">👁</button></div>
          <div id="acctErr" class="acct-error"></div>
          <button class="btn btn-gold" style="width:100%;margin-top:12px" onclick="G.doLoginAction()">✅ เข้าสู่ระบบ</button>
        </div>`:`
        <div style="padding:0 4px 12px">
          <div style="font-size:12px;color:#94a3b8;margin-bottom:4px">ชื่อผู้ใช้ (3–20 ตัวอักษร)</div>
          <input id="acctUser" class="setting-input" type="text" maxlength="20" placeholder="username..." autocomplete="username"/>
          <div style="font-size:12px;color:#94a3b8;margin:10px 0 4px">รหัสผ่าน (อย่างน้อย 4 ตัว)</div>
          <div class="pass-wrap"><input id="acctPass" class="setting-input" type="password" maxlength="40" placeholder="password..." autocomplete="new-password"/><button type="button" class="pass-eye" onclick="G.togglePassEye('acctPass',this)" tabindex="-1" aria-label="แสดง/ซ่อนรหัสผ่าน">👁</button></div>
          <div id="acctErr" class="acct-error"></div>
          <button class="btn btn-gold" style="width:100%;margin-top:12px" onclick="G.doRegisterAction()">📝 สมัครสมาชิก</button>
        </div>`}`;
  }

  function switchAccountTab(tab){ renderAccountModal(tab); }

  function doLoginAction(){
    const u=(document.getElementById('acctUser').value||'').trim();
    const p=document.getElementById('acctPass').value||'';
    const err=document.getElementById('acctErr');
    if(!u||!p){ err.textContent='กรุณากรอกข้อมูลให้ครบ'; return; }
    const db=getUsers();
    if(!db[u]){ err.textContent='ไม่พบชื่อผู้ใช้นี้'; return; }
    if(db[u].password!==p){ err.textContent='รหัสผ่านไม่ถูกต้อง'; return; }
    localStorage.setItem('imm_remember', u);
    setSession(u); init(); loadGameData(); updateAccountDisplay();
    hideRegister();
  }

  function doRegisterAction(){
    const u=(document.getElementById('acctUser').value||'').trim();
    const p=document.getElementById('acctPass').value||'';
    const err=document.getElementById('acctErr');
    if(!/^[A-Za-z0-9_ก-๙]{3,20}$/.test(u)){ err.textContent='ชื่อผู้ใช้ใช้ได้เฉพาะ a-z A-Z 0-9 _ ภาษาไทย (3–20 ตัว)'; return; }
    if(p.length<4){ err.textContent='รหัสผ่านต้องมีอย่างน้อย 4 ตัวอักษร'; return; }
    const db=getUsers();
    // เช็คชื่อซ้ำ (ใช้ Object.keys กันปัญหาชื่อแปลกๆ เช่น toString)
    if(Object.keys(db).indexOf(u) !== -1){ err.textContent='ชื่อผู้ใช้นี้มีอยู่แล้ว'; return; }
    db[u]={ password:p, save:null };
    saveUsersDB(db); localStorage.setItem('imm_remember', u); setSession(u); init(); updateAccountDisplay();
    hideRegister();
  }

  // ออกจากระบบ แล้วเปิดหน้าเข้าสู่ระบบ (แท็บ login) ให้เลย
  function doLogout(){
    saveGameData(); setSession(''); init(); updateAccountDisplay();
    show('titleScreen');
    renderAccountModal('login'); document.getElementById('registerModal').classList.add('open');
  }


  function togglePassEye(id, btn){
      var inp = document.getElementById(id);
      if(!inp) return;
      var show = inp.type === 'password';
      inp.type = show ? 'text' : 'password';
      btn.textContent = show ? '🙈' : '👁';
  }


  let introNext = null;
  function playIntro(next){
      introNext = next;
      var scr = document.getElementById('introScreen');
      var vid = document.getElementById('introVideo');
      document.getElementById('introSkip').classList.remove('visible');
      scr.classList.add('active');
      vid.currentTime = 0;
      vid.muted = false;  // triggered by user tap, so sound is allowed
      vid.play().catch(function(){
          vid.muted = true;  // fall back to muted if the browser still refuses
          vid.play().catch(function(){ introSkipFn(); });
      });
  }

  function introSkipFn(){
      var vid = document.getElementById('introVideo');
      var fade = document.getElementById('introFade');
      vid.pause();
      fade.classList.add('out');
      setTimeout(function(){
          document.getElementById('introScreen').classList.remove('active');
          fade.classList.remove('out');
          if(introNext){ var n = introNext; introNext = null; n(); }
          else { show('titleScreen'); }
      }, 620);
  }

  function showRegister(){ renderAccountModal(); document.getElementById('registerModal').classList.add('open'); }
  function hideRegister(){ document.getElementById('registerModal').classList.remove('open'); }

  init();
  if(getSession()) loadGameData();
  updateAccountDisplay();
  show('titleScreen');
  if(!getSession()){ renderAccountModal(); document.getElementById('registerModal').classList.add('open'); }
  // Intro wiring: plays via playIntro() when the player presses start.
  (function(){
      var scr = document.getElementById('introScreen');
      var vid = document.getElementById('introVideo');
      var skip = document.getElementById('introSkip');
      vid.addEventListener('ended', introSkipFn);
      // tap anywhere on the intro → reveal skip button
      scr.addEventListener('pointerdown', function(e){
          if(e.target === skip) return;
          skip.classList.add('visible');
      });
  })();
  return { introSkipFn, togglePassEye, goTitle, goSeasons, doResult, restart, showItems, hideItems, useItem, showHeroLab, hideHeroLab, showEncyclopedia, hideEncyclopedia, showSettings, hideSettings, toggleSetting, resetProgress, showRegister, hideRegister, switchAccountTab, doLoginAction, doRegisterAction, doLogout, openChest, collectLoot, showUpgradeModal, hideUpgradeModal, spendSP, closeFact, answerQuiz, nextQuizQ };
})();
